    action(settings,Language::text("Bild als Frame importieren…"),{},[this]{auto path=QFileDialog::getOpenFileName(this,Language::text("Frame importieren"),{},Language::text("Bilder (*.png *.bmp *.jpg)"));if(path.isEmpty())return;QImage image(path);if(image.isNull()){appendLog(Language::text("Bild konnte nicht geöffnet werden."));return;}image=image.scaled(128,64,Qt::IgnoreAspectRatio,Qt::SmoothTransformation);const auto name=QString("frame_%1").arg(QDateTime::currentMSecsSinceEpoch());QString code="\n#include <Arduino.h>\nconst uint8_t "+name+"[1024] PROGMEM = {\n";for(int y=0;y<64;++y){code+="    ";for(int bx=0;bx<16;++bx){unsigned b=0;for(int bit=0;bit<8;++bit){auto c=image.pixelColor(bx*8+bit,y);if(c.alpha()>127&&qGray(c.rgb())>=128)b|=0x80u>>bit;}code+=QString("0x%1,").arg(b,2,16,QChar('0'));}code+='\n';}code+="};\n// In loop(): display.drawBitmap(0, 0, "+name+", 128, 64, SSD1306_WHITE);\n";if(auto* editor=qobject_cast<QPlainTextEdit*>(codeTabs_->currentWidget())){editor->moveCursor(QTextCursor::Start);editor->insertPlainText(code);}});
